'use strict';
// The export object is an accessor whose getter answers 0 on the fifth read and an object otherwise.
let reads = 0;

function current() {
	reads += 1;
	console.log('fifth-zero: read', reads);
	return reads === 5 ? 0 : {reads};
}

Object.defineProperty(module, 'exports', {enumerable: true, get: current});
